class Solution {
public:
    long long minimumMoves(vector<int>& nums, int k, int maxChanges) {
        int n = nums.size();
        vector<long long> pos;
        for (int i = 0; i < n; ++i) if (nums[i] == 1) pos.push_back(i);
        int c = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] == 1) {
                int cnt = 1;
                if (i > 0 && nums[i - 1] == 1) cnt++;
                if (i + 1 < n && nums[i + 1] == 1) cnt++;
                c = max(c, cnt);
            }
        }
        c = min(c, k);
        if (maxChanges >= k - c) return max(0, c - 1) + 2LL * (k - c);
        int m = pos.size();
        vector<long long> pref(m + 1, 0);
        for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + pos[i];
        long long ans = 1e18;
        int size = k - maxChanges;
        for (int i = 0; i <= m - size; ++i) {
            int mid = i + size / 2;
            long long p_mid = pos[mid];
            long long left_cnt = mid - i;
            long long right_cnt = i + size - 1 - mid;
            long long left_cost = p_mid * left_cnt - (pref[mid] - pref[i]);
            long long right_cost = (pref[i + size] - pref[mid + 1]) - p_mid * right_cnt;
            long long cost = left_cost + right_cost + 2LL * maxChanges;
            ans = min(ans, cost);
        }
        return ans;
    }
};

class Solution {
    public long minimumMoves(int[] nums, int k, int maxChanges) {
        int n = nums.length;
        List<Long> pos = new ArrayList<>();
        for (int i = 0; i < n; i++) if (nums[i] == 1) pos.add((long) i);
        int c = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                int cnt = 1;
                if (i > 0 && nums[i - 1] == 1) cnt++;
                if (i + 1 < n && nums[i + 1] == 1) cnt++;
                c = Math.max(c, cnt);
            }
        }
        c = Math.min(c, k);
        if (maxChanges >= k - c) return Math.max(0, c - 1) + 2L * (k - c);
        int m = pos.size();
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + pos.get(i);
        long ans = Long.MAX_VALUE;
        int size = k - maxChanges;
        for (int i = 0; i <= m - size; i++) {
            int mid = i + size / 2;
            long pMid = pos.get(mid);
            long leftCnt = mid - i;
            long rightCnt = i + size - 1 - mid;
            long leftCost = pMid * leftCnt - (pref[mid] - pref[i]);
            long rightCost = (pref[i + size] - pref[mid + 1]) - pMid * rightCnt;
            long cost = leftCost + rightCost + 2L * maxChanges;
            ans = Math.min(ans, cost);
        }
        return ans;
    }
}

var minimumMoves = function(nums, k, maxChanges) {
    const n = nums.length;
    const pos = [];
    for (let i = 0; i < n; ++i) if (nums[i] === 1) pos.push(BigInt(i));
    let c = 0;
    for (let i = 0; i < n; ++i) {
        if (nums[i] === 1) {
            let cnt = 1;
            if (i > 0 && nums[i - 1] === 1) cnt++;
            if (i + 1 < n && nums[i + 1] === 1) cnt++;
            c = Math.max(c, cnt);
        }
    }
    c = Math.min(c, k);
    if (maxChanges >= k - c) return Math.max(0, c - 1) + 2 * (k - c);
    const m = pos.length;
    const pref = new Array(m + 1).fill(0n);
    for (let i = 0; i < m; ++i) pref[i + 1] = pref[i] + pos[i];
    let ans = -1n;
    const size = k - maxChanges;
    for (let i = 0; i <= m - size; ++i) {
        const mid = i + Math.floor(size / 2);
        const pMid = pos[mid];
        const leftCnt = BigInt(mid - i);
        const rightCnt = BigInt(i + size - 1 - mid);
        const leftCost = pMid * leftCnt - (pref[mid] - pref[i]);
        const rightCost = (pref[i + size] - pref[mid + 1]) - pMid * rightCnt;
        const cost = leftCost + rightCost + 2n * BigInt(maxChanges);
        if (ans === -1n || cost < ans) ans = cost;
    }
    return Number(ans);
};
